import 'package:flutter/material.dart';
import '../services/donation_checkout_service.dart';
class DonationCheckoutScreen extends StatefulWidget{const DonationCheckoutScreen({super.key,required this.service});final DonationCheckoutService service;@override State<DonationCheckoutScreen> createState()=>_State();}
class _State extends State<DonationCheckoutScreen>{final amount=TextEditingController();final phone=TextEditingController();List gateways=[];int? gatewayId;bool busy=false;@override void initState(){super.initState();widget.service.gateways().then((v){if(mounted)setState(()=>gateways=(v['data']??v) as List);});}
 Future<void> _pay()async{final a=double.tryParse(amount.text);if(a==null||a<=0||gatewayId==null)return;setState(()=>busy=true);try{final v=await widget.service.donate(gatewayId:gatewayId!,amount:a,phone:phone.text.trim());if(mounted)showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('Donation started'),content:Text(v['message']??v['status']?.toString()??'Follow the payment instructions.'),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('OK'))]));}finally{if(mounted)setState(()=>busy=false);}}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Donate')),body:ListView(padding:const EdgeInsets.all(16),children:[TextField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Amount (UGX)')),TextField(controller:phone,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'Mobile number')),DropdownButtonFormField<int>(value:gatewayId,decoration:const InputDecoration(labelText:'Payment method'),items:[for(final g in gateways)DropdownMenuItem(value:g['id'] as int,child:Text(g['name'].toString()))],onChanged:(v)=>setState(()=>gatewayId=v)),const SizedBox(height:24),FilledButton(onPressed:busy?null:_pay,child:Text(busy?'Processing…':'Continue to payment'))]));}
